def enrich(identity,row,summary):
    key=row['type']+'.'+row['name']
    if key in NOTES:return NOTES[key],'body-reviewed'
    token=int(row['token'],16)&0xffffff
    if identity=='EOS.EOSClient' and token in PROTECTION:return 'Injected compression helper: '+PROTECTION[token]+' This is protector support, not an exam feature.','body-reviewed'
    if identity=='EOS.EOSClient' and token in EOS_UI:return EOS_UI[token],'body-reviewed'
    if identity=='EOS.HashCodeProvider' and token==1:return 'Original IL calls Object.GetHashCode nonvirtually: identity hashing bypasses overrides. The first decompile was incorrect. Readable source now uses RuntimeHelpers.GetHashCode, including the observed null → 0 result; differential probes cover both cases.','body-reviewed-and-corrected'
    if not summary.startswith('Recovered implementation'):return summary,'explained-or-structural'
    if key.endswith('TestCase/<>c.<LoadTestCase>b__') or row['name'].startswith('<LoadTestCase>'):return 'Compiler-generated ordering selector: returns the directory name so PRN test-case directories can be sorted.','structural'
    # No claims of manual review for small display/forwarding bodies discovered by inspection.
    if len(row.get('fields') or [])==1 and not row.get('calls'):
        return 'Small model operation on '+row['fields'][0]+'. The complete assignment/read expression is shown below.','structural'
    return summary,'needs-review'
